					if (roof < 0.5) diffuseColor.rgb = wallAge(diffuseColor.rgb, vCW, vCN, vLY, vCS.y, abs(vLN.z) > 0.5 ? (0.5 - abs(vLP.x)) * vCS.x : (0.5 - abs(vLP.z)) * vCS.z, age, pxW, 0.05);
					else diffuseColor.rgb = roofAge(diffuseColor.rgb, vCW, vCN, age);
